<script setup>
import { computed, onMounted, ref } from 'vue'; import { ArrowLeft, Check, CreditCard, MapPin } from 'lucide-vue-next'; import { RouterLink, useRouter } from 'vue-router'; import { useCartStore } from '../stores/cart'; import { orderService } from '../services/orderService'; import { addressService } from '../services/addressService';
const cart = useCartStore(); const router = useRouter(); const addresses = ref([]); const address = ref(null); const payment = ref('card'); const loading = ref(false); const error = ref(''); const subtotal = computed(() => cart.subtotal);
onMounted(async () => { await cart.fetch(); try { addresses.value = (await addressService.list()).data.addresses || []; address.value = addresses.value.find(item => item.is_default) || addresses.value[0] || null; } catch { /* Address is optional in the existing checkout API. */ } });
async function placeOrder() { loading.value = true; error.value = ''; try { const { data } = await orderService.create(); router.push(`/order-success/${data.id}`); } catch (e) { error.value = e.response?.data?.message || 'The order could not be placed.'; } finally { loading.value = false; } }
</script>
<template><section class="container page-section"><RouterLink class="back-link" to="/cart"><ArrowLeft :size="16" /> Back to cart</RouterLink><div class="section-heading checkout-heading"><div><p class="kicker">FINAL REVIEW</p><h1>Checkout</h1></div><span class="checkout-lock"><Check :size="15" /> Secure checkout</span></div><div v-if="!cart.items.length" class="state">Your cart is empty. <RouterLink to="/products">Browse products</RouterLink></div><div v-else class="checkout-layout"><div class="checkout-main"><section class="checkout-section"><div class="checkout-section-title"><span>1</span><div><h3>Delivery address</h3><p>Saved for your records; the current order API calculates from your cart.</p></div></div><div v-if="address" class="address-box"><MapPin :size="18" /><span><b>{{ address.name }}</b><br>{{ address.street }}, {{ address.city }}, {{ address.state }} {{ address.postal_code }}, {{ address.country }}</span></div><p v-else class="muted">No saved address yet. Your order will still be created by the existing API.</p></section><section class="checkout-section"><div class="checkout-section-title"><span>2</span><div><h3>Products</h3><p>{{ cart.count }} items in your server cart</p></div></div><div v-for="item in cart.items" :key="item.id" class="checkout-item"><img v-if="item.product.image_url" :src="item.product.image_url" :alt="item.product.name"><div v-else class="cart-thumb">N</div><span>{{ item.product.name }} <small>Qty {{ item.quantity }}</small></span><strong>${{ (item.product.price * item.quantity).toLocaleString() }}</strong></div></section><section class="checkout-section"><div class="checkout-section-title"><span>3</span><div><h3>Payment method</h3><p>Selection is presented here; the current API does not accept payment details.</p></div></div><label class="payment-option"><input v-model="payment" type="radio" value="card"><CreditCard :size="19" /><span><b>Card on delivery</b><small>Payment handling remains with your current backend flow.</small></span></label></section><p v-if="error" class="form-error">{{ error }}</p></div><aside class="summary"><h3>Order summary</h3><div><span>Subtotal</span><strong>${{ subtotal.toLocaleString(undefined, { minimumFractionDigits: 2 }) }}</strong></div><div><span>Shipping</span><strong>Included</strong></div><hr><div class="summary-total"><span>Total</span><strong>${{ subtotal.toLocaleString(undefined, { minimumFractionDigits: 2 }) }}</strong></div><button class="button button-accent full-button" :disabled="loading" @click="placeOrder">{{ loading ? 'Placing order...' : 'Place order' }} <Check :size="16" /></button><small>Final total is calculated by Laravel when the order is created.</small></aside></div></section></template>
